//! **Frequency lexicon** (Phase 14 step 2, 2026-05-29) —
//! 2804-entry extension built from the top of the unigram-
//! frequency list extracted over
//! `data/curated/{wikipedia_kz,cc100_kk,kazakh_textbooks}_pack.json`
//! (318k clean Cyrillic sentences; 228k distinct native-letter
//! tokens; loanword filter drops every word containing
//! «ё ц щ ъ ь э»). Words already present in the original
//! curated set (303 entries across alphabet / nouns / verbs /
//! misc / expanded) are skipped to keep `full_lexicon()` free
//! of duplicate Cyrillic strings.
//!
//! Each entry's phoneme decomposition is the output of
//! `cyrillic_to_phonemes(..., is_native_root=true)` via
//! `tools/lexicon_gen`, so the v6.3 strict-orthographic
//! «ы» / «і» rule is baked in by construction. POS is
//! defaulted to `Noun` — the STT path only consumes the
//! phoneme sequence; downstream NLU code that needs real
//! POS should either skip this module or rely on the
//! morpheme analyser, not on this static tag.
//!
//! Two raw entries were dropped by the generator («іі»,
//! «ііі») — strict-«і»-drop collapses them to the empty
//! phoneme sequence. They were almost certainly OCR noise.

